-- Tags: no-fasttest
-- no-fasttest: requires the ORC input format, which is not built in fasttest.

-- The native ORC reader maps ORC's union type to the ClickHouse Variant type.

SET allow_experimental_variant_type = 1;

-- Sparse union<int32, string>, rows: (int 10), (str 'x'), (int 30), (str 'z').
DESC format(ORC, unhex(''));
SELECT u, toTypeName(u) FROM format(ORC, unhex('')) ORDER BY toString(u);

-- The same logical data written as a dense union.
SELECT u FROM format(ORC, unhex('')) ORDER BY toString(u);

-- Variant sorts and de-duplicates its branch types: union<string, int32, double> -> Variant(Float64, Int32, String),
-- and the ORC tags are remapped to the sorted discriminators.
DESC format(ORC, unhex(''));
SELECT u, toTypeName(u) FROM format(ORC, unhex('')) ORDER BY toString(u);

-- A non-null ORC union row can still select a branch whose payload is null (here the string branch
-- of row 2). Variant branches are non-nullable, so such a row must become a Variant NULL, not the
-- branch's default value. Rows: (int 10), (string NULL), (int 30), (string 'z').
SELECT u, toTypeName(u) FROM format(ORC, unhex('')) ORDER BY toString(u);

-- A union with two branches of the same type cannot be represented as a Variant.
SELECT * FROM format(ORC, unhex('')) FORMAT Null; -- { serverError CANNOT_EXTRACT_TABLE_STRUCTURE }

-- A malformed ORC file with an out-of-range union tag must fail cleanly, not crash (previously a
-- heap-buffer-overflow in the Arrow-based ORC reader).
SELECT * FROM format(ORC, unhex('')) FORMAT Null; -- { serverError INCORRECT_DATA }

-- A malformed ORC file whose stripe footer has fewer column encodings than the schema
-- declares columns must fail cleanly during schema inference, not crash (previously an
-- out-of-bounds read of the stripe footer in the ORC library aborted the process). Here a
-- union branch's column id has no matching column encoding in the stripe footer.
SELECT * FROM format(ORC, unhex('')) FORMAT Null; -- { serverError CANNOT_EXTRACT_TABLE_STRUCTURE }
